function validate([tree, target]) {
  if (!Array.isArray(tree) || tree.length === 0 || tree[0] === null) return 'The tree needs at least one node.';
  // In level order, the item at index i is a child of the floor((i - 1) / 2)-th node seen so far.
  let nodes = 0;
  for (let i = 0; i < tree.length; i++) {
    if (i > 0 && Math.floor((i - 1) / 2) >= nodes) return 'Every value after the root needs a parent node before it.';
    if (tree[i] !== null) nodes++;
  }
  const values = tree.filter(v => v !== null);
  if (values.length > 10000) return 'The tree has at most 10^4 nodes.';
  if (values.some(v => !Number.isSafeInteger(v))) return 'Node values are integers.';
  if (new Set(values).size !== values.length) return 'Node values must be distinct.';
  if (!values.includes(target)) return 'target must be the value of a node in the tree.';
  return null;
}

