function adapt(input, solve, kit) {
  const [tree, target] = input;
  const original = kit.toTree(tree);
  const cloned = kit.toTree(tree);
  // List each tree's nodes with an explicit stack so that deep trees need no recursion here.
  const collect = root => {
    const nodes = [];
    const stack = [root];
    while (stack.length) {
      const node = stack.pop();
      nodes.push(node);
      if (node.right) stack.push(node.right);
      if (node.left) stack.push(node.left);
    }
    return nodes;
  };
  const originalNodes = collect(original);
  const clonedNodes = collect(cloned);
  const links = nodes => nodes.map(node => [node.val, node.left, node.right]);
  const before = [links(originalNodes), links(clonedNodes)];
  const intact = (nodes, saved) => nodes.every((node, i) => node.val === saved[i][0] && node.left === saved[i][1] && node.right === saved[i][2]);
  const result = solve(original, cloned, originalNodes.find(node => node.val === target));
  if (!intact(originalNodes, before[0]) || !intact(clonedNodes, before[1])) throw new Error('Neither tree may be modified.');
  if (result === undefined) throw new Error('The solution did not return a value.');
  if (result === null) return null;
  if (new Set(originalNodes).has(result)) throw new Error('Return the node from the cloned tree, not the one from the original tree.');
  if (!new Set(clonedNodes).has(result)) throw new Error('Return a node of the cloned tree.');
  return result.val;
}

