  // Walk both trees level by level in lockstep; each queue entry pairs a node with its copy.
  const pairs = [[original, cloned]];
  for (let i = 0; i < pairs.length; i++) {
    const [a, b] = pairs[i];
    if (a === target) return b;
    if (a.left) pairs.push([a.left, b.left]);
    if (a.right) pairs.push([a.right, b.right]);
